class ShipmentStatus(BaseModel):
    order_id: str
    status: Literal["processing", "in_transit", "out_for_delivery",
                     "delivered", "exception"]
    eta: str | None
    sla_breached: bool

@tool
def track_shipment(order_id: str) -> dict:
    """Get the current delivery status of ONE order by its id.
    Use for 'where is my order' questions. Do NOT use for refunds.
    order_id format: TW-YYYY-NNNNN (e.g. TW-2026-88120)."""
    # errors are RETURN VALUES, never raises
    if not order_id.startswith("TW-"):
        return {"error": "invalid_order_id_format"}
    record = _oms.get_order(order_id)
    if record is None:
        return {"error": "order_not_found"}
    return ShipmentStatus(
        order_id=order_id, status=record.status,
        eta=record.eta_iso, sla_breached=record.sla_breached,
    ).model_dump()

def guarded_tool(mcp, *, domain: str):
    def _decorator(func):
        @functools.wraps(func)
        def _wrapped(*args, **kwargs):
            agent_id = kwargs.get("agent_id")
            customer_id = kwargs.get("customer_id")
            session_cid = kwargs.pop("session_customer_id", None)
            if not agent_id or not customer_id:
                return {"error": "missing_authz_context"}
            # TEACHING POINT: checked BEFORE the tool body runs at all
            if not agent_may_access(agent_id, func.__name__, customer_id,
                                     session_customer_id=session_cid):
                _audit(func.__name__, domain, agent_id, customer_id,
                       ok=False, code="not_authorised")
                return {"error": "not_authorised"}
            result = func(*args, **kwargs)         # only now does it run
            _audit(func.__name__, domain, agent_id, customer_id, ok=True)
            return result
        if MCP_AVAILABLE and mcp is not None:
            mcp.tool()(_wrapped)
        return _wrapped
    return _decorator

