def agent_may_access(agent_id, tool_name, customer_id, **ctx) -> bool:
    """The ONE function every MCP server checks before executing —
    never trust a prompt instruction to have already handled it."""
    return explain(agent_id, tool_name, customer_id, **ctx).allowed
